"""Sales data and the pure helpers the dashboard uses (no streamlit here)."""

SALES = [
    {"order": 1, "region": "North", "product": "mug", "amount": 120.0},
    {"order": 2, "region": "South", "product": "pen", "amount": 35.5},
    {"order": 3, "region": "North", "product": "lamp", "amount": 260.0},
    {"order": 4, "region": "East", "product": "mug", "amount": 80.0},
    {"order": 5, "region": "South", "product": "desk", "amount": 410.0},
    {"order": 6, "region": "North", "product": "pen", "amount": 40.0},
    {"order": 7, "region": "East", "product": "lamp", "amount": 240.0},
    {"order": 8, "region": "South", "product": "chair", "amount": 200.0},
]


def make_sales():
    return [dict(row) for row in SALES]


def regions(rows):
    return sorted({r["region"] for r in rows})


def filter_sales(rows, region, minimum):
    return [r for r in rows
            if (region == "All" or r["region"] == region) and r["amount"] >= minimum]


def totals_by_region(rows):
    out = {}
    for r in rows:
        out[r["region"]] = out.get(r["region"], 0.0) + r["amount"]
    return [{"region": k, "total": round(v, 2)} for k, v in sorted(out.items())]

