import streamlit as st

from app import data

st.set_page_config(page_title="Sales", layout="wide")


@st.cache(allow_output_mutation=True)
def load_sales():
    return data.make_sales()


@st.experimental_memo
def region_totals(rows):
    return data.totals_by_region(rows)


@st.experimental_singleton
def visit_counter():
    return {"visits": 0}


def share_view():
    st.experimental_set_query_params(region=st.session_state.region)


if "ready" not in st.session_state:
    params = st.experimental_get_query_params()
    st.session_state.region = params.get("region", ["All"])[0]
    st.session_state.ready = True
    visit_counter()["visits"] += 1
    st.experimental_rerun()

sales = load_sales()
st.title("Sales dashboard")
st.selectbox("Region", ["All"] + data.regions(sales), key="region")
minimum = st.slider("Minimum amount", 0, 300, 0, step=50)
view = data.filter_sales(sales, st.session_state.region, minimum)
st.metric("Orders", len(view))
st.metric("Revenue", round(sum(r["amount"] for r in view), 2))
st.table(region_totals(view))
st.button("Share this view", on_click=share_view)
st.caption("visits: %d" % visit_counter()["visits"])

